prob = load_problem('data/Call_300_Vehicle_90.txt')

def print_feasibility(sol):
    feasibility, c = feasibility_check(sol, prob)

    print(sol)
    print(feasibility)  
    print(c)


def check_validity(sol):
    vehicle_count = sol.count(0)
    call_counts = {i: sol.count(i) for i in range(1, prob['n_calls'] + 1)}

    assert vehicle_count == prob['n_vehicles']
    for call, count in call_counts.items():
        assert count == 2

